CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY);
CREATE TABLE organisations (id text PRIMARY KEY, name text NOT NULL, max_runs int NOT NULL DEFAULT 2 CHECK(max_runs > 0));
CREATE TABLE users (id text PRIMARY KEY, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('human','agent')));
CREATE TABLE memberships (org_id text REFERENCES organisations, user_id text REFERENCES users, PRIMARY KEY(org_id,user_id));
CREATE TABLE repositories (id text PRIMARY KEY, org_id text REFERENCES organisations NOT NULL, full_name text NOT NULL, target_ref text NOT NULL DEFAULT 'main', base_sha text NOT NULL, max_changes int NOT NULL DEFAULT 1 CHECK(max_changes>0), UNIQUE(org_id,id));
CREATE TABLE projects (id text PRIMARY KEY, org_id text REFERENCES organisations NOT NULL, name text NOT NULL, repo_id text NOT NULL, UNIQUE(org_id,id), FOREIGN KEY(org_id,repo_id) REFERENCES repositories(org_id,id));
CREATE TABLE project_access (org_id text NOT NULL, project_id text NOT NULL, user_id text NOT NULL, contribute boolean NOT NULL DEFAULT false, review boolean NOT NULL DEFAULT false, merge boolean NOT NULL DEFAULT false, PRIMARY KEY(project_id,user_id), FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id), FOREIGN KEY(org_id,user_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id text REFERENCES users NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE provider_connections (id text PRIMARY KEY, org_id text NOT NULL REFERENCES organisations, project_id text NOT NULL, user_id text NOT NULL, provider text NOT NULL CHECK(provider='codex'), secret_ref text, mode text NOT NULL CHECK(mode IN ('fixture','byok-proposed')), enabled boolean NOT NULL DEFAULT false, FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id), FOREIGN KEY(org_id,user_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE skills (id text NOT NULL, version text NOT NULL, org_id text NOT NULL, project_id text NOT NULL, digest text NOT NULL, instructions text NOT NULL, enabled boolean NOT NULL DEFAULT false, PRIMARY KEY(id,version), FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
CREATE TABLE tasks (id text PRIMARY KEY, org_id text NOT NULL, project_id text NOT NULL, title text NOT NULL, outcome text NOT NULL, criteria jsonb NOT NULL, priority text NOT NULL CHECK(priority IN ('High','Medium','Low')), state text NOT NULL DEFAULT 'todo' CHECK(state IN ('todo','building','review','publishing','code_review','merging','completed','blocked','cancelled')), version int NOT NULL DEFAULT 1, generation int NOT NULL DEFAULT 0, candidate_id text, merged_sha text, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,project_id,id), FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id), CHECK(state <> 'completed' OR (merged_sha IS NOT NULL AND completed_at IS NOT NULL)));
CREATE TABLE dependencies (org_id text NOT NULL, project_id text NOT NULL, task_id text NOT NULL, depends_on text NOT NULL, PRIMARY KEY(task_id,depends_on), FOREIGN KEY(org_id,project_id,task_id) REFERENCES tasks(org_id,project_id,id), FOREIGN KEY(org_id,project_id,depends_on) REFERENCES tasks(org_id,project_id,id), CHECK(task_id<>depends_on));
CREATE TABLE claims (id text PRIMARY KEY, org_id text NOT NULL, project_id text NOT NULL, task_id text NOT NULL, owner_id text NOT NULL REFERENCES users, repo_id text NOT NULL, released_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,project_id,task_id,id), FOREIGN KEY(org_id,project_id,task_id) REFERENCES tasks(org_id,project_id,id), FOREIGN KEY(org_id,repo_id) REFERENCES repositories(org_id,id));
CREATE UNIQUE INDEX one_active_claim ON claims(task_id) WHERE released_at IS NULL;
CREATE TABLE runs (id text PRIMARY KEY, org_id text NOT NULL, project_id text NOT NULL, task_id text NOT NULL, claim_id text NOT NULL, generation int NOT NULL, state text NOT NULL CHECK(state IN ('queued','running','unknown','stopped')), stopped_at timestamptz, stop_proof text, heartbeat_at timestamptz, manifest jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,project_id,task_id,id), FOREIGN KEY(org_id,project_id,task_id,claim_id) REFERENCES claims(org_id,project_id,task_id,id), CHECK((state='stopped') = (stopped_at IS NOT NULL AND stop_proof IS NOT NULL)));
CREATE UNIQUE INDEX one_active_execution ON runs(claim_id) WHERE stopped_at IS NULL;
CREATE TABLE candidates (id text PRIMARY KEY, org_id text NOT NULL, project_id text NOT NULL, task_id text NOT NULL, run_id text NOT NULL, generation int NOT NULL, digest text NOT NULL, manifest jsonb NOT NULL, evidence jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,project_id,task_id,id), FOREIGN KEY(org_id,project_id,task_id,run_id) REFERENCES runs(org_id,project_id,task_id,id));
ALTER TABLE tasks ADD FOREIGN KEY(org_id,project_id,id,candidate_id) REFERENCES candidates(org_id,project_id,task_id,id);
CREATE FUNCTION immutable_candidate() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Candidates are immutable'; END $$;
CREATE TRIGGER immutable_candidate BEFORE UPDATE OR DELETE ON candidates FOR EACH ROW EXECUTE FUNCTION immutable_candidate();
CREATE TABLE approvals (id text PRIMARY KEY, org_id text NOT NULL, project_id text NOT NULL, task_id text NOT NULL, candidate_id text NOT NULL, action text NOT NULL CHECK(action IN ('publish','merge')), digest text NOT NULL, approver_id text NOT NULL REFERENCES users, policy_version text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, consumed_at timestamptz, FOREIGN KEY(org_id,project_id,task_id,candidate_id) REFERENCES candidates(org_id,project_id,task_id,id));
CREATE TABLE jobs (id text PRIMARY KEY, org_id text NOT NULL, project_id text NOT NULL, task_id text NOT NULL, run_id text, approval_id text REFERENCES approvals, kind text NOT NULL CHECK(kind IN ('execute','publish','merge')), state text NOT NULL DEFAULT 'ready' CHECK(state IN ('ready','processing','uncertain','done','blocked')), attempts int NOT NULL DEFAULT 0, lease_until timestamptz, lease_token text, available_at timestamptz NOT NULL DEFAULT now(), error text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(org_id,project_id,task_id) REFERENCES tasks(org_id,project_id,id));
CREATE TABLE publications (operation_id text PRIMARY KEY REFERENCES jobs, org_id text NOT NULL, project_id text NOT NULL, task_id text NOT NULL, candidate_id text NOT NULL, pr_number int NOT NULL, url text NOT NULL, head_sha text NOT NULL, merged_sha text, FOREIGN KEY(org_id,project_id,task_id,candidate_id) REFERENCES candidates(org_id,project_id,task_id,id));
CREATE TABLE comments (id text PRIMARY KEY, org_id text NOT NULL, project_id text NOT NULL, task_id text, user_id text REFERENCES users NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id), FOREIGN KEY(org_id,project_id,task_id) REFERENCES tasks(org_id,project_id,id));
CREATE TABLE events (id bigserial PRIMARY KEY, org_id text NOT NULL, project_id text NOT NULL, task_id text, actor_id text REFERENCES users, kind text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
CREATE INDEX events_project_cursor ON events(project_id,id);
CREATE TABLE receipts (user_id text NOT NULL REFERENCES users, project_id text NOT NULL REFERENCES projects, key text NOT NULL, payload_hash text NOT NULL, response jsonb NOT NULL, PRIMARY KEY(user_id,project_id,key));
CREATE TABLE preview_grants (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users, candidate_id text NOT NULL REFERENCES candidates, expires_at timestamptz NOT NULL);
-- Fixture state is durable so restart/timeout tests exercise reconciliation, not process memory.
CREATE TABLE fixture_external (operation_id text PRIMARY KEY, kind text NOT NULL, result jsonb NOT NULL);
INSERT INTO schema_migrations VALUES ('001');
